    // ---------------------------------------------------------------- cargo

    #[test]
    fn cargo_publish_argv_uses_manifest_path_and_locked_with_no_registry_for_default() {
        let dir = tempfile::tempdir().unwrap();
        let manifest = dir.path().join("Cargo.toml");
        std::fs::write(&manifest, "[package]\nname = \"demo\"\nversion = \"1.0.0\"\n").unwrap();

        let argv = cargo_publish_argv(dir.path(), Path::new("."), "demo", &v("1.0.0"), None).unwrap();
        assert_eq!(argv.program, "cargo");
        assert!(argv.args.contains(&"--locked".to_string()));
        assert!(argv.args.contains(&"--manifest-path".to_string()));
        assert!(!argv.args.iter().any(|a| a == "--registry"));
        assert_eq!(argv.cwd, dir.path());
    }

    #[test]
    fn cargo_publish_runs_in_the_directory_of_the_workspace_that_governs_the_package() {
        let dir = tempfile::tempdir().unwrap();
        let write = |path: &str, text: &str| {
            let path = dir.path().join(path);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, text).unwrap();
        };
        write("native/Cargo.toml", "[workspace]\nmembers = [\"crates/*\"]\n");
        write(
            "native/crates/a/Cargo.toml",
            "[package]\nname = \"a\"\nversion = \"0.3.0\"\n",
        );

        let argv = cargo_publish_argv(dir.path(), Path::new("native/crates/a"), "a", &v("0.3.0"), None).unwrap();
        assert_eq!(argv.cwd, dir.path().join("native"));
        assert!(argv.args.contains(
            &dir.path()
                .join("native/crates/a/Cargo.toml")
                .to_string_lossy()
                .into_owned()
        ));
    }

    #[test]
    fn cargo_publish_argv_adds_registry_flag_when_non_default() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname = \"demo\"\nversion = \"2.0.0\"\n",
        )
        .unwrap();

        let argv = cargo_publish_argv(dir.path(), Path::new("."), "demo", &v("2.0.0"), Some("my-registry")).unwrap();
        assert!(argv.args.windows(2).any(|w| w == ["--registry", "my-registry"]));
    }

    #[test]
    fn cargo_publish_argv_rejects_ondisk_version_mismatch() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname = \"demo\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();

        let err = cargo_publish_argv(dir.path(), Path::new("."), "demo", &v("2.0.0"), None).unwrap_err();
        assert!(
            matches!(err, GraphError::OnDiskVersionDrift { .. }),
            "expected OnDiskVersionDrift, got: {err:?}"
        );
    }

    #[test]
    fn cargo_publish_argv_resolves_workspace_inherited_version() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[workspace]\nmembers = [\"crates/demo\"]\n\n[workspace.package]\nversion = \"3.1.4\"\n",
        )
        .unwrap();
        let crate_dir = dir.path().join("crates/demo");
        std::fs::create_dir_all(&crate_dir).unwrap();
        std::fs::write(
            crate_dir.join("Cargo.toml"),
            "[package]\nname = \"demo\"\nversion.workspace = true\n",
        )
        .unwrap();

        let argv = cargo_publish_argv(dir.path(), Path::new("crates/demo"), "demo", &v("3.1.4"), None).unwrap();
        assert!(argv
            .args
            .iter()
            .any(|a| a.ends_with("crates/demo/Cargo.toml") || a.ends_with("crates\\demo\\Cargo.toml")));
    }

    // ------------------------------------------------------------------ npm

    #[test]
    fn detects_pnpm_from_lockfile() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("pnpm-lock.yaml"), "").unwrap();
        assert_eq!(detect_npm_package_manager(dir.path()).unwrap(), NpmPackageManager::Pnpm);
    }

    #[test]
    fn detects_yarn_from_lockfile() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("yarn.lock"), "").unwrap();
        assert_eq!(detect_npm_package_manager(dir.path()).unwrap(), NpmPackageManager::Yarn);
    }

    #[test]
    fn detects_bun_from_binary_lockfile() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("bun.lockb"), "").unwrap();
        assert_eq!(detect_npm_package_manager(dir.path()).unwrap(), NpmPackageManager::Bun);
    }

    #[test]
    fn detects_bun_from_text_lockfile() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("bun.lock"), "").unwrap();
        assert_eq!(detect_npm_package_manager(dir.path()).unwrap(), NpmPackageManager::Bun);
    }

    #[test]
    fn defaults_to_npm_with_no_recognized_lockfile() {
        let dir = tempfile::tempdir().unwrap();
        assert_eq!(detect_npm_package_manager(dir.path()).unwrap(), NpmPackageManager::Npm);
    }

    /// Discovery reads a pnpm workspace from `pnpm-workspace.yaml`; so does publishing, lockfile or not.
    #[test]
    fn a_pnpm_workspace_file_without_a_lockfile_is_still_pnpm() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("pnpm-workspace.yaml"), "packages:\n  - 'packages/*'\n").unwrap();
        assert_eq!(detect_npm_package_manager(dir.path()).unwrap(), NpmPackageManager::Pnpm);
    }

    /// A directory that cannot be searched is an error, not a quiet fall back to `npm`.
    #[cfg(unix)]
    #[test]
    fn an_uninspectable_workspace_is_an_error_not_npm() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempfile::tempdir().unwrap();
        let locked = dir.path().join("locked");
        std::fs::create_dir(&locked).unwrap();
        std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o000)).unwrap();
        let result = detect_npm_package_manager(&locked);
        std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o755)).unwrap();
        if std::fs::read_dir(&locked).is_ok() && result.is_ok() {
            // Running with privileges that ignore directory modes (root): nothing to observe.
            return;
        }
        assert!(result.is_err(), "{result:?}");
    }

    /// A package in a nested workspace publishes with that workspace's tool, from that workspace's directory.
    #[test]
    fn a_nested_workspace_publishes_from_its_own_directory() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join("web/packages/a")).unwrap();
        std::fs::write(
            dir.path().join("web/pnpm-workspace.yaml"),
            "packages:\n  - 'packages/*'\n",
        )
        .unwrap();
        let workspace = crate::workspace_owner::npm_workspace_dir(dir.path(), Path::new("web/packages/a")).unwrap();
        let workspace_root = dir.path().join(&workspace);
        let manager = detect_npm_package_manager(&workspace_root).unwrap();
        let argv = npm_publish_argv(&workspace_root, Path::new("packages/a"), "a", manager, None, None, None);
        assert_eq!(argv.program, "pnpm");
        assert_eq!(argv.cwd, dir.path().join("web"));
    }

    #[test]
    fn pnpm_publish_argv_uses_filter_and_no_git_checks() {
        let argv = npm_publish_argv(
            Path::new("/workspace"),
            Path::new("packages/a"),
            "pkg-a",
            NpmPackageManager::Pnpm,
            None,
            None,
            None,
        );
        assert_eq!(argv.program, "pnpm");
        assert_eq!(argv.args, vec!["publish", "--filter=pkg-a", "--no-git-checks"]);
        assert_eq!(argv.cwd, Path::new("/workspace"));
    }

    #[test]
    fn yarn_publish_argv_uses_workspace_npm_publish() {
        let argv = npm_publish_argv(
            Path::new("/workspace"),
            Path::new("packages/a"),
            "pkg-a",
            NpmPackageManager::Yarn,
            None,
            None,
            None,
        );
        assert_eq!(argv.program, "yarn");
        assert_eq!(argv.args, vec!["workspace", "pkg-a", "npm", "publish"]);
        assert_eq!(argv.cwd, Path::new("/workspace"));
    }

    #[test]
    fn bun_publish_argv_runs_from_package_dir() {
        let argv = npm_publish_argv(
            Path::new("/workspace"),
            Path::new("packages/a"),
            "pkg-a",
            NpmPackageManager::Bun,
            None,
            None,
            None,
        );
        assert_eq!(argv.program, "bun");
        assert_eq!(argv.args, vec!["publish"]);
        assert_eq!(argv.cwd, Path::new("/workspace/packages/a"));
    }

    #[test]
    fn npm_publish_argv_uses_workspace_flag() {
        let argv = npm_publish_argv(
            Path::new("/workspace"),
            Path::new("packages/a"),
            "pkg-a",
            NpmPackageManager::Npm,
            None,
            None,
            None,
        );
        assert_eq!(argv.program, "npm");
        assert_eq!(argv.args, vec!["publish", "--workspace=pkg-a"]);
    }

    #[test]
    fn npm_publish_argv_appends_tag_access_and_registry() {
        let argv = npm_publish_argv(
            Path::new("/workspace"),
            Path::new("packages/a"),
            "pkg-a",
            NpmPackageManager::Npm,
            Some("next"),
            Some(NpmAccess::Public),
            Some("https://registry.example.com"),
        );
        assert_eq!(
            argv.args,
            vec![
                "publish",
                "--workspace=pkg-a",
                "--tag",
                "next",
                "--access",
                "public",
                "--registry",
                "https://registry.example.com",
            ]
        );
    }

    /// Each argv was checked against the real tool's `publish --help` (pnpm 10, yarn 4.9, bun 1.2, npm 11): yarn's
    /// `npm publish` accepts `--access` and `--tag` but rejects `--registry`, and reads `publishConfig.registry` itself.
    #[test]
    fn every_package_manager_gets_only_the_publish_flags_it_accepts() {
        let argv = |manager| {
            npm_publish_argv(
                Path::new("/workspace"),
                Path::new("packages/a"),
                "pkg-a",
                manager,
                Some("next"),
                Some(NpmAccess::Public),
                Some("https://registry.example.com"),
            )
        };
        let flags = ["--tag", "next", "--access", "public"];
        let registry = ["--registry", "https://registry.example.com"];
        let expect = |base: &[&str], with_registry: bool| -> Vec<String> {
            let mut args: Vec<String> = base.iter().chain(&flags).map(|arg| (*arg).to_owned()).collect();
            if with_registry {
                args.extend(registry.iter().map(|arg| (*arg).to_owned()));
            }
            args
        };
        assert_eq!(
            argv(NpmPackageManager::Pnpm).args,
            expect(&["publish", "--filter=pkg-a", "--no-git-checks"], true)
        );
        assert_eq!(
            argv(NpmPackageManager::Yarn).args,
            expect(&["workspace", "pkg-a", "npm", "publish"], false)
        );
        let bun = argv(NpmPackageManager::Bun);
        assert_eq!(bun.args, expect(&["publish"], true));
        assert_eq!(
            bun.cwd,
            Path::new("/workspace/packages/a"),
            "bun publishes the directory it runs in"
        );
        assert_eq!(
            argv(NpmPackageManager::Npm).args,
            expect(&["publish", "--workspace=pkg-a"], true)
        );
    }

    #[test]
    fn scoped_npm_package_without_explicit_access_publishes_public() {
        assert_eq!(npm_default_access("@s/cli", None), Some(NpmAccess::Public));
        assert_eq!(npm_default_access("cli", None), None);
        assert_eq!(
            npm_default_access("@s/cli", Some(NpmAccess::Restricted)),
            Some(NpmAccess::Restricted)
        );
        let by_name = npm_publish_argv(
            Path::new("/workspace"),
            Path::new("packages/a"),
            "@s/cli",
            NpmPackageManager::Npm,
            None,
            None,
            None,
        );
        let by_directory = npm_publish_directory_argv(
            Path::new("/workspace"),
            Path::new(""),
            Path::new("npm/x"),
            "@s/cli-x",
            None,
            None,
            None,
        );
        for args in [&by_name.args, &by_directory.args] {
            assert!(args.windows(2).any(|pair| pair == ["--access", "public"]), "{args:?}");
        }
    }

    // ----------------------------------------------------------------- pypi

    #[test]
    fn pypi_build_argv_builds_both_distributions_into_the_given_directory() {
        let build = pypi_build_argv(
            Path::new("/workspace"),
            Path::new("packages/my-pkg"),
            Path::new("/tmp/out"),
            1_700_000_000,
        )
        .unwrap();
        assert_eq!(build.program, "env");
        assert_eq!(build.args[0], "SOURCE_DATE_EPOCH=1700000000");
        assert!(
            build.args[1] == "python3" || build.args[1] == "python",
            "{}",
            build.args[1]
        );
        assert_eq!(
            build.args[2..],
            ["-m", "build", "--sdist", "--wheel", "--outdir", "/tmp/out"]
        );
        assert_eq!(build.cwd, Path::new("/workspace/packages/my-pkg"));
    }

    /// Only the named files are uploaded, with no glob and no `--skip-existing` for any target.
    #[test]
    fn pypi_upload_argv_names_each_file_and_never_skips_existing() {
        let files = [
            PathBuf::from("/tmp/out/my_pkg-1.2.3-py3-none-any.whl"),
            PathBuf::from("/tmp/out/my_pkg-1.2.3.tar.gz"),
        ];
        for index in [
            None,
            Some("https://upload.pypi.org/legacy/"),
            Some("http://127.0.0.1:4873/"),
        ] {
            let upload = pypi_upload_argv(Path::new("/workspace"), Path::new("packages/my-pkg"), index, &files);
            assert_eq!(upload.program, "twine");
            assert!(
                !upload.args.contains(&"--skip-existing".to_string()),
                "{:?}",
                upload.args
            );
            assert!(upload.args.iter().all(|arg| !arg.contains('*')), "{:?}", upload.args);
            assert_eq!(
                &upload.args[upload.args.len() - 2..],
                ["/tmp/out/my_pkg-1.2.3-py3-none-any.whl", "/tmp/out/my_pkg-1.2.3.tar.gz",]
            );
            assert_eq!(upload.cwd, Path::new("/workspace/packages/my-pkg"));
        }
    }

    #[test]
    fn pypi_upload_argv_targets_a_private_index() {
        let upload = pypi_upload_argv(
            Path::new("/workspace"),
            Path::new("."),
            Some("https://pypi.example.com/legacy/"),
            &[PathBuf::from("/tmp/out/a.whl")],
        );
        assert_eq!(
            upload.args,
            vec![
                "upload",
                "--repository-url",
                "https://pypi.example.com/legacy/",
                "/tmp/out/a.whl"
            ]
        );
    }

    #[test]
    fn resolve_python_interpreter_prefers_python3_over_python() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("python3"), "").unwrap();
        std::fs::write(dir.path().join("python"), "").unwrap();
        let path = std::env::join_paths([dir.path()]).unwrap();

        assert_eq!(resolve_python_interpreter(Some(&path)).unwrap(), "python3");
    }

    #[test]
    fn resolve_python_interpreter_falls_back_to_python() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("python"), "").unwrap();
        let path = std::env::join_paths([dir.path()]).unwrap();

        assert_eq!(resolve_python_interpreter(Some(&path)).unwrap(), "python");
    }

    #[test]
    fn resolve_python_interpreter_errors_naming_both_when_neither_found() {
        let dir = tempfile::tempdir().unwrap();
        let path = std::env::join_paths([dir.path()]).unwrap();

        let err = resolve_python_interpreter(Some(&path)).unwrap_err();
        let message = err.to_string();
        assert!(message.contains("python3"), "{message}");
        assert!(message.contains("python"), "{message}");
    }

    #[test]
    fn resolve_python_interpreter_errors_when_path_is_unset() {
        let err = resolve_python_interpreter(None).unwrap_err();
        assert!(matches!(
            err,
            GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::PythonInterpreterOnPath
            }
        ));
    }

    // ---------------------------------------------------------- classification

    #[test]
    fn classify_cargo_output_recognizes_already_exists() {
        let out = output(101, "", "error: crate version `1.0.0` is already uploaded");
        assert!(matches!(
            classify_cargo_output(&out),
            Ok(PublishOutcome::AlreadyPublished)
        ));
    }

    #[test]
    fn classify_cargo_output_success_is_published() {
        let out = output(0, "Uploading demo v1.0.0", "");
        assert!(matches!(classify_cargo_output(&out), Ok(PublishOutcome::Published)));
    }

    #[test]
    fn classify_cargo_output_rate_limit_is_detected() {
        let out = output(1, "", "error: too many requests, retry after 30 seconds");
        match classify_cargo_output(&out) {
            Err(RegistryError::RateLimited(dur)) => assert_eq!(dur, Duration::from_secs(30)),
            other => panic!("expected RateLimited, got {other:?}"),
        }
    }

    #[test]
    fn classify_cargo_output_ignores_bare_429_in_byte_counts() {
        let out = output(1, "", "429.1KiB compressed; some other failure");
        match classify_cargo_output(&out) {
            Err(RegistryError::Other(_)) => {}
            other => panic!("bare 429 byte count must not be classified as rate-limited, got {other:?}"),
        }
    }

    #[test]
    fn classify_cargo_output_redacts_secrets_in_error_message() {
        temp_env::with_var("CARGO_REGISTRY_TOKEN", Some("super-secret-token-value"), || {
            let out = output(1, "", "authentication failed: token super-secret-token-value invalid");
            let err = classify_cargo_output(&out).unwrap_err();
            assert!(
                !err.to_string().contains("super-secret-token-value"),
                "secret must be redacted from error message, got: {err}"
            );
        });
    }

    #[test]
    fn classify_npm_publish_output_recognizes_conflict_as_already_published() {
        let out = output(1, "", "npm ERR! code E409\nnpm ERR! 409 Conflict");
        assert!(matches!(
            classify_npm_publish_output(&out),
            Ok(PublishOutcome::AlreadyPublished)
        ));
    }

    #[test]
    fn classify_npm_publish_output_auth_failure() {
        let out = output(1, "", "npm ERR! code E401\nnpm ERR! 401 authentication required");
        assert!(matches!(
            classify_npm_publish_output(&out),
            Err(RegistryError::AuthFailed(_))
        ));
    }

    #[test]
    fn classify_twine_output_all_skipped_is_already_published() {
        let out = output(0, "Skipping my_pkg-1.0.0a0-py3-none-any.whl (already exists)", "");
        assert!(matches!(
            classify_twine_output(&out),
            Ok(PublishOutcome::AlreadyPublished)
        ));
    }

    #[test]
    fn classify_twine_output_mixed_skip_and_upload_is_published() {
        let out = output(
            0,
            "Skipping my_pkg-1.0.0a0-py3-none-any.whl (already exists)\nUploading my_pkg-1.0.0-py3-none-any.whl",
            "",
        );
        assert!(matches!(classify_twine_output(&out), Ok(PublishOutcome::Published)));
    }

    #[test]
    fn classify_twine_output_failure_is_other() {
        let out = output(1, "", "some unrecognized failure");
        assert!(matches!(classify_twine_output(&out), Err(RegistryError::Other(_))));
    }

    /// Twine prints its progress and errors to stdout, so a failure names the files that went up first.
    #[test]
    fn classify_twine_output_failure_reports_the_progress_on_stdout() {
        let out = output(
            1,
            "Uploading my_pkg-1.0.0-py3-none-any.whl\nUploading my_pkg-1.0.0.tar.gz\nHTTPError: 503 Service Unavailable\n",
            "",
        );
        let Err(RegistryError::Other(message)) = classify_twine_output(&out) else {
            panic!("a failed upload is an error");
        };
        assert!(message.contains("Uploading my_pkg-1.0.0-py3-none-any.whl"), "{message}");
        assert!(message.contains("503"), "{message}");
    }

    /// A failing run that mentions "already exists" is never reported as published.
    #[test]
    fn classify_twine_output_a_failing_run_is_never_already_published() {
        let out = output(1, "", "HTTPError: 400 File already exists");
        assert!(matches!(classify_twine_output(&out), Err(RegistryError::Other(_))));
    }

    /// Without `--skip-existing` (private index, or a race against the
    /// preflight observation), a real conflict is a typed error, not a
    /// guessed `AlreadyPublished` -- captured verbatim from a real
    /// `pypiserver` 409 response, which carries no "already exist" text.
    #[test]
    fn classify_twine_output_private_index_conflict_without_skip_existing_is_a_typed_error() {
        let out = output(1, "", "HTTPError: 409 Conflict from http://127.0.0.1:18081/\nConflict");
        assert!(matches!(classify_twine_output(&out), Err(RegistryError::Other(_))));
    }
}

