1	//! The npm registry adapter: how a npm publish is observed, classified and run.
2	
3	use super::*;
4	
5	pub(super) fn run_npm_publish_argv(
6	    context: &ProviderContext<'_>,
7	    argv: &registry_argv::Argv,
8	    timeout: Duration,
9	) -> Result<CommandOutput, GraphError> {
10	    let token = std::env::var("NPM_TOKEN").ok().filter(|value| !value.is_empty());
11	    let config = std::env::var("CALLISTO_PUBLISH_NPM_CONFIG")
12	        .ok()
13	        .filter(|value| !value.is_empty());
14	    let env = npm_publisher_environment(&argv.program, token.as_deref(), config.as_deref());
15	    let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
16	    Ok(context
17	        .runner()
18	        .run_with_timeout_publisher(&argv.program, &args, &argv.cwd, timeout, &env)?)
19	}
20	
21	pub(super) fn npm_publisher_environment<'a>(
22	    program: &str,
23	    token: Option<&'a str>,
24	    config: Option<&'a str>,
25	) -> Vec<(&'static str, &'a str)> {
26	    let mut env = Vec::new();
27	    if let Some(token) = token {
28	        env.push(("NPM_TOKEN", token));
29	        if program == "bun" {
30	            env.push(("NPM_CONFIG_TOKEN", token));
31	        }
32	    }
33	    if let Some(config) = config {
34	        env.push(("NPM_CONFIG_USERCONFIG", config));
35	    }
36	    env
37	}
38	
39	/// The code npm gives a registry 404 for a package or a version.
40	pub(super) const NPM_NOT_FOUND_CODE: &str = "E404";
41	
42	/// Only npm's own `E404` code proves absence, never text around it; any other failure is a retried `CommandFailed`.
43	pub(super) fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
44	    if output.success() {
45	        return if output.stdout_trimmed().is_empty() {
46	            transient(ProviderIndeterminateCause::MalformedResponse, None)
47	        } else {
48	            settled(ProviderObservationV1::Exact {
49	                evidence: ProviderEvidenceV1::RegistryVersion {
50	                    version: version.clone(),
51	                    checksum: None,
52	                    yanked: None,
53	                },
54	            })
55	        };
56	    }
57	    let code = if output.stdout_trimmed().is_empty() {
58	        npm_stderr_code(&output.stderr)
59	    } else {
60	        npm_error_code(&output.stdout)
61	    };
62	    if code.as_deref() == Some(NPM_NOT_FOUND_CODE) {
63	        return settled(ProviderObservationV1::Absent);
64	    }
65	    transient(ProviderIndeterminateCause::CommandFailed, None)
66	}
67	
68	/// The repository URL in `npm view <spec> repository --json`: a string, or an object with a `url`.
69	pub(super) fn npm_view_repository(stdout: &str) -> Option<String> {
70	    let value: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
71	    match value {
72	        serde_json::Value::String(url) => Some(url),
73	        serde_json::Value::Object(map) => map.get("url")?.as_str().map(str::to_owned),
74	        _ => None,
75	    }
76	    .filter(|url| !url.is_empty())
77	}
78	
79	/// The `error.code` of the JSON error body `npm --json` prints to stdout on failure.
80	pub(super) fn npm_error_code(stdout: &str) -> Option<String> {
81	    let body: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
82	    body.get("error")?.get("code")?.as_str().map(str::to_owned)
83	}
84	
85	/// The code on npm's `npm ERR! code X` or `npm error code X` stderr line; npm 8 prints no JSON body.
86	pub(super) fn npm_stderr_code(stderr: &str) -> Option<String> {
87	    stderr.lines().find_map(|line| {
88	        let rest = line
89	            .strip_prefix("npm ERR! ")
90	            .or_else(|| line.strip_prefix("npm error "))?;
91	        rest.strip_prefix("code ").map(|code| code.trim().to_owned())
92	    })
93	}
94	
95	pub(super) struct NpmRegistry;
96	
97	impl RegistryEcosystem for NpmRegistry {
98	    fn ecosystem(&self) -> Ecosystem {
99	        Ecosystem::Npm
100	    }
101	
102	    fn defers_confirmation(&self) -> bool {
103	        true
104	    }
105	
106	    fn repository(&self, context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Option<String> {
107	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
108	        let mut args = vec!["view", spec.as_str(), "repository", "--json", "--fetch-retries=0"];
109	        if let Some(registry) = operation.registry.endpoint.as_deref() {
110	            args.extend(["--registry", registry]);
111	        }
112	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir).ok()?;
113	        let output = run_observation(
114	            context.runner(),
115	            programs::NPM,
116	            &args,
117	            &context.root().join(workspace_dir),
118	            timeouts::REGISTRY_QUERY,
119	            true,
120	        )
121	        .ok()?
122	        .ok()?;
123	        output.success().then(|| npm_view_repository(&output.stdout)).flatten()
124	    }
125	
126	    fn can_observe_versions(&self) -> bool {
127	        true
128	    }
129	
130	    /// `npm view` never reads the local package; its cwd is only where the project `.npmrc` supplying the registry is
131	    /// read from. That must be where publishing runs, or the two could address different registries, so it is the
132	    /// workspace that owns the package.
133	    fn observe_once(
134	        &self,
135	        context: &ProviderContext<'_>,
136	        operation: &RegistryPublishOperation,
137	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
138	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
139	        // Callisto's bounded retry owns retrying; npm's own fetch retries made an
140	        // unreachable registry take ~70s per attempt.
141	        let mut args = vec!["view", spec.as_str(), "--json", "--fetch-retries=0"];
142	        if let Some(registry) = operation.registry.endpoint.as_deref() {
143	            args.extend(["--registry", registry]);
144	        }
145	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir)?;
146	        let output = match run_observation(
147	            context.runner(),
148	            programs::NPM,
149	            &args,
150	            &context.root().join(workspace_dir),
151	            timeouts::REGISTRY_QUERY,
152	            true,
153	        )? {
154	            Ok(output) => output,
155	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
156	        };
157	        Ok(classify_npm_view(&output, &operation.version))
158	    }
159	
160	    fn publish(
161	        &self,
162	        context: &ProviderContext<'_>,
163	        _id: &ReleaseOperationId,
164	        operation: &RegistryPublishOperation,
165	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
166	    ) -> Result<CommandOutput, GraphError> {
167	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir)?;
168	        if operation.by_directory {
