1	//! The workspace that owns a package, resolved once and used everywhere a command must run "in the workspace".
2	//!
3	//! Each tool reads its project configuration (`.npmrc`, registries, credentials) and resolves `--workspace` from the
4	//! directory it runs in, and a lockfile sits beside the workspace root. If publishing, observing and refreshing each
5	//! guessed that directory their own way they could disagree about it, so they all ask here. The owner is the nearest
6	//! directory at or above the package whose manifest declares a workspace, the same declaration discovery reads; only for
7	//! a package no workspace declares does a lockfile or marker file decide.
8	
9	use std::path::{Path, PathBuf};
10	
11	use crate::error::GraphError;
12	use crate::locate::{declares_npm_workspace, declares_python_workspace};
13	
14	/// Files that mark a directory as the root of an npm-family project even though no workspace is declared in it.
15	pub(crate) const NPM_LOCKFILES: [&str; 5] = [
16	    "package-lock.json",
17	    "pnpm-lock.yaml",
18	    "yarn.lock",
19	    "bun.lock",
20	    "bun.lockb",
21	];
22	pub(crate) const PYPI_LOCKFILES: [&str; 4] = ["uv.lock", "poetry.lock", "pdm.lock", "Pipfile.lock"];
23	
24	/// The npm workspace directory, relative to `root`, that owns the package at `package_dir`.
25	///
26	/// # Errors
27	///
28	/// A manifest or marker on the way up cannot be read or understood.
29	pub(crate) fn npm_workspace_dir(root: &Path, package_dir: &Path) -> Result<PathBuf, GraphError> {
30	    let markers: Vec<&str> = NPM_LOCKFILES.iter().copied().chain(["pnpm-workspace.yaml"]).collect();
31	    owner(root, package_dir, declares_npm_workspace, &markers)
32	}
33	
34	/// The Python (uv) workspace directory, relative to `root`, that owns the package at `package_dir`.
35	///
36	/// # Errors
37	///
38	/// A manifest or marker on the way up cannot be read or understood.
39	pub(crate) fn python_workspace_dir(root: &Path, package_dir: &Path) -> Result<PathBuf, GraphError> {
40	    owner(root, package_dir, declares_python_workspace, &PYPI_LOCKFILES)
41	}
42	
43	fn owner(
44	    root: &Path,
45	    package_dir: &Path,
46	    declares: impl Fn(&Path) -> Result<bool, crate::locate::LocateError>,
47	    markers: &[&str],
48	) -> Result<PathBuf, GraphError> {
49	    let dirs: Vec<&Path> = package_dir.ancestors().collect();
50	    for dir in &dirs {
51	        if declares(&root.join(dir))? {
52	            return Ok(relative(dir));
53	        }
54	    }
55	    for dir in &dirs {
56	        for marker in markers {
57	            let path = root.join(dir).join(marker);
58	            let present = callisto_model::strict_fs::exists(&path).map_err(|error| GraphError::ReleaseInputRead {
59	                path: path.clone(),
60	                message: error.to_string(),
61	            })?;
62	            if present {
63	                return Ok(relative(dir));
64	            }
65	        }
66	    }
67	    Ok(PathBuf::new())
68	}
