70	/// `.` is the root, spelled as an empty path like everywhere else a directory is relative to it.
71	fn relative(dir: &Path) -> PathBuf {
72	    if dir == Path::new(".") {
73	        PathBuf::new()
74	    } else {
75	        dir.to_path_buf()
76	    }
77	}
