505	/// Answers each `npm view` with the next scripted output, repeating the last one.
506	struct SequencedNpm(std::sync::Mutex<std::collections::VecDeque<CommandOutput>>);
507	
508	impl CommandRunner for SequencedNpm {
509	    fn run(&self, _program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, callisto_model::CommandError> {
510	        let mut outputs = self.0.lock().unwrap();
511	        Ok(if outputs.len() > 1 {
512	            outputs.pop_front().expect("checked non-empty")
513	        } else {
514	            outputs.front().expect("a scripted output").clone()
515	        })
516	    }
517	}
518	
519	/// The waits spent confirming an npm publish whose `npm view` answers are `outputs`, and what the confirmation saw.
520	fn confirm_npm(
521	    outputs: Vec<CommandOutput>,
522	    confirm_timeout: Option<std::time::Duration>,
523	) -> (ProviderObservationV1, Vec<std::time::Duration>) {
524	    let runner = SequencedNpm(std::sync::Mutex::new(outputs.into()));
525	    let sleeper = RecordingSleeper::new();
526	    let root = std::env::temp_dir();
527	    let context = ProviderContext::new(&root, &runner, None).with_sleeper(&sleeper);
528	    let mut operation = operation("npm", "callisto-no-such-package-zz", "1.0.0");
529	    operation.registry.confirm_timeout = confirm_timeout;
530	    let observation =
531	        confirmed_registry_observation(adapter_for(Ecosystem::Npm).unwrap(), &context, &operation).unwrap();
532	    (observation, sleeper.waits())
533	}
