222	/// The one bounded retry in the release path. It wraps read-only observations
223	/// only: an effect (publish, push, release create, asset upload) is never
224	/// re-issued from here, because a transient error cannot prove the first
225	/// attempt did not take effect.
226	pub(crate) fn retry_observation<T>(
227	    sleeper: &dyn Sleeper,
228	    attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
229	) -> Result<T, GraphError> {
230	    retry_observation_within(sleeper, None, attempt)
231	}
