233	/// [`retry_observation`] that stops retrying once `patience` of waiting is spent, and reports the last answer. A
234	/// caller that is itself waiting out a window gives its look the window that is left, so a registry that asks for
235	/// long waits cannot hold the look past it.
236	pub(crate) fn retry_observation_within<T>(
237	    sleeper: &dyn Sleeper,
238	    patience: Option<Duration>,
239	    mut attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
240	) -> Result<T, GraphError> {
241	    let mut exhausted = None;
242	    let mut waited = Duration::ZERO;
243	    for index in 0..OBSERVATION_MAX_ATTEMPTS {
244	        match attempt()? {
245	            Attempt::Settled(value) => return Ok(value),
246	            Attempt::Transient { value, retry_after } => {
247	                exhausted = Some(value);
248	                if index + 1 < OBSERVATION_MAX_ATTEMPTS {
249	                    let wait = retry_after
250	                        .unwrap_or_else(|| observation_backoff(index))
251	                        .min(OBSERVATION_BACKOFF_CAP);
252	                    let wait = patience.map_or(wait, |patience| wait.min(patience.saturating_sub(waited)));
253	                    if wait.is_zero() && patience.is_some() {
254	                        break;
255	                    }
256	                    sleeper.sleep(wait);
257	                    waited += wait;
258	                }
259	            }
260	        }
261	    }
262	    Ok(exhausted.expect("at least one attempt always runs"))
263	}
