265	/// A successful publish-client exit isn't a receipt: confirms the registry
266	/// itself has caught up before treating the operation as done. If not, it
267	/// stays `Attempting` for reconciliation, reported via its own variant
268	/// rather than `ReleaseIntentStale`'s false "no operation was authorized".
269	pub(crate) fn require_registry_confirmation(
270	    is_published: bool,
271	    package: &str,
272	    version: &Version,
273	    waited: Duration,
274	) -> Result<(), GraphError> {
275	    if is_published {
276	        return Ok(());
277	    }
278	    Err(GraphError::RegistryPublishUnconfirmed {
279	        package: package.to_string(),
280	        version: version.clone(),
281	        waited,
282	    })
283	}
