610	    /// Records the schedule instead of waiting it out.
611	    pub(crate) struct RecordingSleeper(std::sync::Mutex<Vec<Duration>>);
612	
613	    impl RecordingSleeper {
614	        pub(crate) fn new() -> Self {
615	            Self(std::sync::Mutex::new(Vec::new()))
616	        }
617	
618	        pub(crate) fn waits(&self) -> Vec<Duration> {
619	            self.0.lock().unwrap().clone()
