213	pub(crate) fn canonical_git_remote(raw: &str) -> Result<PreparedGitRemote, GraphError> {
214	    let ssh_url = if raw.starts_with("git@") && !raw.contains("//") {
215	        let (host, path) =
216	            raw.strip_prefix("git@")
217	                .and_then(|value| value.split_once(':'))
218	                .ok_or(GraphError::UnsafeGitRemote {
219	                    reason: "invalid SSH remote syntax",
220	                })?;
221	        format!("ssh://git@{host}/{path}")
222	    } else {
223	        raw.to_string()
224	    };
225	    let parsed = url::Url::parse(&ssh_url).map_err(|error| GraphError::UnsafeGitRemote {
226	        reason: url_parse_error_reason(error),
227	    })?;
228	    if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
229	        return Err(GraphError::UnsafeGitRemote {
230	            reason: "URL must have an authority",
231	        });
232	    }
233	    if !matches!(parsed.scheme(), "https" | "ssh") {
234	        return Err(GraphError::UnsafeGitRemote {
235	            reason: "URL scheme must be HTTPS or SSH",
236	        });
237	    }
238	    if parsed.REDACTEDword().is_some() || parsed.query().is_some() || parsed.fragment().is_some() {
239	        return Err(GraphError::UnsafeGitRemote {
240	            reason: "credentials, query strings, and fragments are forbidden",
241	        });
242	    }
243	    if parsed.scheme() == "https" && !parsed.username().is_empty() {
244	        return Err(GraphError::UnsafeGitRemote {
245	            reason: "HTTPS userinfo is forbidden",
246	        });
247	    }
248	    if parsed.scheme() == "ssh" && parsed.username() != "git" {
249	        return Err(GraphError::UnsafeGitRemote {
250	            reason: "SSH remotes must use the git account",
251	        });
252	    }
253	    let host = parsed.host_str().expect("validated authority").to_ascii_lowercase();
254	    let mut components = parsed.path_segments().ok_or(GraphError::UnsafeGitRemote {
255	        reason: "remote path is invalid",
256	    })?;
257	    let owner = components
258	        .next()
259	        .filter(|value| !value.is_empty())
260	        .ok_or(GraphError::UnsafeGitRemote {
261	            reason: "remote path must name an owner and repository",
262	        })?;
263	    let repository = components
264	        .next()
265	        .filter(|value| !value.is_empty())
266	        .ok_or(GraphError::UnsafeGitRemote {
267	            reason: "remote path must name an owner and repository",
268	        })?;
269	    if components.next().is_some() || owner == "." || owner == ".." || repository == "." || repository == ".." {
270	        return Err(GraphError::UnsafeGitRemote {
271	            reason: "remote path must contain exactly an owner and repository",
272	        });
273	    }
274	    let repository = repository.strip_suffix(".git").unwrap_or(repository);
275	    if repository.is_empty() {
276	        return Err(GraphError::UnsafeGitRemote {
277	            reason: "repository name is empty",
278	        });
279	    }
280	    let port = parsed.port_or_known_default();
281	    let port_text = match (parsed.scheme(), port) {
282	        ("https", Some(443)) | ("ssh", Some(22)) | (_, None) => String::new(),
283	        (_, Some(port)) => format!(":{port}"),
284	    };
285	    let endpoint = match parsed.scheme() {
286	        "https" => format!("https://{host}{port_text}/{owner}/{repository}.git"),
287	        "ssh" => format!("ssh://git@{host}{port_text}/{owner}/{repository}.git"),
288	        _ => unreachable!("scheme checked above"),
289	    };
290	    let mut transcript = CanonicalTranscript::semantic_input_v1();
291	    transcript.push_str("gitRemote.scheme", parsed.scheme());
292	    transcript.push_str("gitRemote.host", &host);
293	    transcript.push_str(
294	        "gitRemote.port",
295	        &port.map_or_else(String::new, |port| port.to_string()),
296	    );
297	    transcript.push_str("gitRemote.owner", owner);
298	    transcript.push_str("gitRemote.repository", repository);
299	    let github_repository = if host == "github.com" {
300	        Some(
301	            GitHubRepository::parse(&format!("{owner}/{repository}")).map_err(|error| GraphError::UnsafeGitRemote {
302	                reason: github_repository_parse_error_reason(&error),
303	            })?,
304	        )
305	    } else {
306	        None
307	    };
308	    Ok(PreparedGitRemote {
309	        endpoint,
310	        identity: SemanticInputDigest::from_transcript(&transcript),
311	        github_repository,
312	    })
313	}
