2	
3	use callisto_model::{CanonicalTranscript, RegistryBindingDigest, RegistryKey};
4	
5	/// Credential-free URL projection used only inside a digest transcript.
6	#[derive(Debug, PartialEq, Eq)]
7	pub(crate) struct RegistryBindingV1 {
8	    pub(crate) scheme: String,
9	    pub(crate) host: String,
10	    pub(crate) effective_port: Option<u16>,
11	    pub(crate) path: String,
12	}
13	
14	impl RegistryBindingV1 {
15	    pub(crate) fn digest(&self) -> RegistryBindingDigest {
16	        let mut transcript = CanonicalTranscript::semantic_input_v1();
17	        transcript.push_str("registry.scheme", &self.scheme);
18	        transcript.push_str("registry.host", &self.host);
19	        transcript.push_str(
20	            "registry.port",
21	            &self.effective_port.map_or_else(String::new, |port| port.to_string()),
