pub trait TimeProvider: Send + Sync {
    fn now(&self) -> std::time::SystemTime;
    fn sleep(&self, duration: Duration);
}

/// Redacts every occurrence of any non-empty string in `secrets` from
/// `text`, replacing each with `[REDACTED]`, then strips any URL userinfo
/// component (`REDACTED` -> `scheme://host`) regardless of
/// whether it matched a known secret.
///
/// Callers use this on raw subprocess stderr before it's embedded in a
/// [`RegistryError`] and, downstream, a JSON report or CI log — registry
/// CLIs (`cargo publish`, `npm publish`, `twine upload`) can echo a
/// credential verbatim in their own error diagnostics on auth failure.
///
/// Pure and injectable (`secrets` rather than reading the environment
/// directly) so it stays deterministic and test-friendly; see
/// [`known_credential_env_values`] for the real caller-side source of
/// `secrets`.
pub fn redact_known_secrets(text: &str, secrets: &[String]) -> String {
    let mut redacted = text.to_string();
    for secret in secrets {
        if !secret.is_empty() {
            redacted = redacted.replace(secret.as_str(), "[REDACTED]");
        }
    }
    redact_url_userinfo(&redact_token_shapes(&redacted))
}

/// Token prefixes, the shortest run after each that counts as a token, so ordinary words are left alone.
const TOKEN_PREFIXES: &[(&str, usize)] = &[
    ("npm_", 20),
    ("ghp_", 20),
    ("gho_", 20),
    ("ghu_", 20),
    ("ghs_", 20),
    ("ghr_", 20),
    ("github_pat_", 20),
    ("pypi-", 20),
];

fn is_token_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, '_' | '-')
}

/// Masks credentials that a registry tool echoes although none of them is in a known environment variable: tokens
/// with a well-known prefix, `Bearer` values and the value of an `.npmrc` `_authToken`, `_auth` or `_password` line.
fn redact_token_shapes(text: &str) -> String {
    let mut redacted = text.to_string();
    for (prefix, min_len) in TOKEN_PREFIXES {
        redacted = mask_after(
            &redacted,
            prefix,
            true,
            |value| value.chars().take_while(|c| is_token_char(*c)).count(),
            *min_len,
        );
    }
    redacted = mask_bearer(&redacted);
    for key in ["_authToken=", "_auth=", "_password="] {
        redacted = mask_after(
            &redacted,
            key,
            false,
            |value| {
                value
                    .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
                    .unwrap_or(value.len())
            },
            1,
        );
    }
    redacted
}

/// Replaces `prefix` plus the value that follows with `[REDACTED]` (a `key=` keeps the key). `value_len` measures the
/// value, in bytes of its leading run, and a value shorter than `min_len` characters is not a credential. A `prefix`
/// glued to a preceding word is not a token start when `word_boundary` is set, and `${NAME}` placeholders are kept.
fn mask_after(
    text: &str,
    prefix: &str,
    word_boundary: bool,
    value_len: impl Fn(&str) -> usize,
    min_len: usize,
) -> String {
    let mut result = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(position) = rest.find(prefix) {
        let (before, from_prefix) = rest.split_at(position);
        let after_prefix = &from_prefix[prefix.len()..];
        let boundary_ok = !word_boundary || before.chars().next_back().is_none_or(|c| !is_token_char(c));
        let measured = value_len(after_prefix);
        let value = &after_prefix[..measured];
        let long_enough = value.chars().count() >= min_len && !value.starts_with("${");
        result.push_str(before);
        if boundary_ok && long_enough {
            if word_boundary {
                result.push_str("[REDACTED]");
            } else {
                result.push_str(prefix);
                result.push_str("[REDACTED]");
            }
            rest = &after_prefix[measured..];
        } else {
            result.push_str(prefix);
            rest = after_prefix;
        }
    }
    result.push_str(rest);
    result
}

/// Masks the credential after `Bearer ` (any case) when it is long enough to be one, so prose such as
/// `Bearer authentication failed` is kept.
fn mask_bearer(text: &str) -> String {
    let lower = text.to_ascii_lowercase();
    let mut result = String::with_capacity(text.len());
    let mut cursor = 0;
    while let Some(found) = lower[cursor..].find("bearer ") {
        let start = cursor + found;
        let value_start = start + "bearer ".len();
        let value_len = text[value_start..]
            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
            .unwrap_or(text.len() - value_start);
        result.push_str(&text[cursor..value_start]);
        if value_len >= 16 {
            result.push_str("[REDACTED]");
            cursor = value_start + value_len;
        } else {
            cursor = value_start;
        }
    }
    result.push_str(&text[cursor..]);
    result
}

/// Filters an env-var snapshot down to registry-credential values this
/// codebase's publish flow reads: the names in [`SECRET_CREDENTIAL_ENV`], plus any
/// `CARGO_REGISTRIES_<NAME>_TOKEN` (operator-configured, unbounded name,
/// so matched by pattern). `GITHUB_TOKEN`/`GH_TOKEN` cover GitHub Actions'
/// ambient credential -- `redact_url_userinfo` already catches its most
/// realistic leak shape (an authenticated remote URL) independently, but
/// matching the env var names directly is cheap insurance against other
/// leak shapes.
///
/// Takes the snapshot as a parameter (callers pass `std::env::vars()`)
/// rather than reading the environment directly -- deterministic, no
/// process-env mutation in tests.
pub fn known_credential_env_values(vars: impl Iterator<Item = (String, String)>) -> Vec<String> {
    vars.filter(|(key, value)| {
        !value.is_empty()
            && (SECRET_CREDENTIAL_ENV.contains(&key.as_str())
                || (key.starts_with("CARGO_REGISTRIES_") && key.ends_with("_TOKEN"))
                || (value.len() >= MIN_SECRET_VALUE_LEN && SECRET_NAME_SUFFIXES.iter().any(|s| key.ends_with(s))))
    })
    .map(|(_, value)| value)
    .collect()
}

/// Any variable named like a secret has its value redacted too, unless the value is so short that masking it would
/// mangle ordinary text.
const SECRET_NAME_SUFFIXES: &[&str] = &["_TOKEN", "_SECRET", "_PASSWORD"];
const MIN_SECRET_VALUE_LEN: usize = 8;

/// The environment variables whose values are secrets. A username and the paths of generated config files
/// (`TWINE_USERNAME`, `NPM_CONFIG_USERCONFIG`, `CALLISTO_PUBLISH_NPM_CONFIG`) are credentials to keep out of
/// unrelated children but are not secret values, so they are not listed.
pub const SECRET_CREDENTIAL_ENV: &[&str] = &[
    "ACTIONS_ID_TOKEN_REQUEST_TOKEN",
    "NPM_TOKEN",
    "NPM_CONFIG_TOKEN",
    "NODE_AUTH_TOKEN",
    "PYPI_TOKEN",
    "TWINE_PASSWORD",
    "CARGO_REGISTRY_TOKEN",
    "GITHUB_TOKEN",
    "GH_TOKEN",
];

/// The one definition of "how this workspace redacts a subprocess's stderr":
/// [`redact_known_secrets`] over [`known_credential_env_values`] of the live
/// environment. Every path that puts child stderr in front of a human -- the
/// live echo, [`crate::CommandOutput::redacted_stderr`], and the
/// `CommandFailure::NonZeroExit` diagnostic -- composes it here rather than
/// repeating the composition, so none of them can drift out of step.
///
/// Reads the environment, so it is deliberately not the pure primitive;
/// unit tests target [`redact_known_secrets`] with an explicit secret list.
pub fn redact_command_stderr(stderr: &str) -> String {
    redact_known_secrets(stderr, &known_credential_env_values(std::env::vars()))
}

/// Strips a URL's userinfo (`user:pass@` between `scheme://` and the
/// host) from every `scheme://...` occurrence in `text`, replacing it
/// with `[REDACTED]@`. Token-by-token: within the span from `scheme://`
/// to the next whitespace/quote/`<`/`>`, everything up to the *last* `@`
/// is treated as userinfo.
///
/// Deliberately conservative, not strictly RFC 3986-aware: userinfo with
/// a raw `/` or a second `@` (an unescaped base64-ish token) is realistic
/// in free-form CLI stderr, and using the *first* `@` would under-redact
/// exactly that case. Cost: a rare false positive (an `@` that's really
/// part of a path, e.g. an npm scoped package in
/// `registry.npmjs.org/@myorg/pkg`, gets redacted too) -- acceptable,
/// since over-redaction only costs log noise while under-redaction leaks
/// a credential.
fn redact_url_userinfo(text: &str) -> String {
    let mut result = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(scheme_pos) = rest.find("://") {
        let split_at = scheme_pos + 3;
        result.push_str(&rest[..split_at]);
        let after = &rest[split_at..];
        let stop = after
            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
            .unwrap_or(after.len());
        let candidate = &after[..stop];
        if let Some(at_pos) = candidate.rfind('@') {
            result.push_str("[REDACTED]@");
            rest = &after[at_pos + 1..];
            continue;
        }
        rest = after;
    }
    result.push_str(rest);
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn redacts_a_known_secret_value_from_text() {
        let text = "npm ERR! 403 Forbidden - PUT https://registry.npmjs.org/pkg - token abc123secret was rejected";
        let redacted = redact_known_secrets(text, &["abc123secret".to_string()]);
        assert!(!redacted.contains("abc123secret"));
        assert!(redacted.contains("[REDACTED]"));
    }

    #[test]
    fn redacts_multiple_occurrences_of_the_same_secret() {
        let text = "token=s3cr3t failed; retrying with token=s3cr3t again";
        let redacted = redact_known_secrets(text, &["s3cr3t".to_string()]);
        assert!(!redacted.contains("s3cr3t"));
        assert_eq!(redacted.matches("[REDACTED]").count(), 2);
    }

    #[test]
    fn leaves_text_unchanged_when_no_secrets_match() {
        let text = "cargo publish failed: crate version already exists";
        let redacted = redact_known_secrets(text, &["unrelated-secret".to_string()]);
        assert_eq!(redacted, text);
    }

    #[test]
    fn empty_string_secret_in_the_list_does_not_corrupt_output() {
        // `"".replace("", "X")` would insert "X" between every character --
        // confirm the empty-secret guard actually prevents that footgun.
        let text = "normal error message";
        let redacted = redact_known_secrets(text, &[String::new(), "real-secret".to_string()]);
        assert_eq!(redacted, text);
    }

    #[test]
    fn redacts_url_userinfo_even_when_it_matches_no_known_secret() {
        // A private-registry URL with embedded basic-auth credentials,
        // echoed verbatim by a registry CLI's own error diagnostics, is
        // not necessarily one of the fixed credential env vars -- this
        // must be caught independently of the `secrets` list.
        let text = "error: failed to fetch REDACTED 401";
        let redacted = redact_known_secrets(text, &[]);
        assert!(!redacted.contains("hunter2"));
        assert!(!redacted.contains("alice"));
        assert_eq!(
            redacted,
            "error: failed to fetch https://[REDACTED]@registry.example.com/pkg.tgz: 401"
        );
    }

    #[test]
    fn redacts_a_prefixed_token_that_is_in_no_known_variable() {
        for token in [
            "REDACTED",
            "REDACTED",
            "REDACTED",
            "REDACTED",
        ] {
            let text = format!("error: 401, token {token} rejected");
            let redacted = redact_known_secrets(&text, &[]);
            assert_eq!(redacted, "error: 401, token [REDACTED] rejected", "{token}");
        }
    }

    #[test]
    fn redacts_a_bearer_credential_but_not_prose_after_the_word() {
        let redacted = redact_known_secrets("extra: auth header Bearer REDACTED here", &[]);
        assert_eq!(redacted, "extra: auth header Bearer [REDACTED] here");
        let prose = "Bearer authentication failed";
        assert_eq!(redact_known_secrets(prose, &[]), prose);
    }

    #[test]
    fn redacts_an_npmrc_credential_value_but_keeps_an_interpolation_placeholder() {
        let redacted = redact_known_secrets("//registry.npmjs.org/:_authToken=abc123def456 was used", &[]);
        assert_eq!(redacted, "//registry.npmjs.org/:_authToken=[REDACTED] was used");
        let placeholder = "//registry.npmjs.org/:_authToken=${NPM_TOKEN}";
        assert_eq!(redact_known_secrets(placeholder, &[]), placeholder);
    }

    #[test]
    fn leaves_words_that_only_resemble_a_token_prefix() {
        for text in [
            "npm_config_cache is unset",
            "see ghp_short",
            "REDACTED",
        ] {
            assert_eq!(redact_known_secrets(text, &[]), text);
        }
    }

    #[test]
    fn a_variable_named_like_a_secret_has_its_value_redacted() {
        let vars = [
            ("DEPLOY_TOKEN", "deploy-secret-value"),
            ("DB_PASSWORD", "hunter2hunter2"),
            ("SHORT_TOKEN", "abc"),
            ("TOKEN_ENDPOINT", "https://example.com"),
            ("PATH", "/usr/bin"),
        ]
        .into_iter()
        .map(|(key, value)| (key.to_string(), value.to_string()));
        assert_eq!(
            known_credential_env_values(vars),
            ["deploy-secret-value".to_string(), "hunter2hunter2".to_string()]
        );
    }

