170	pub(super) fn classify_pypi_simple(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
171	    classify_pypi_status(
172	        output,
173	        |body| classify_pypi_simple_body(body, version),
174	        ProviderObservationV1::Absent,
175	        |cause| ProviderObservationV1::Indeterminate { cause },
176	    )
177	}
