279	    /// Runs the build into `outdir`, with file timestamps pinned to the release commit.
280	    pub(crate) fn build_into(
281	        context: &ProviderContext<'_>,
282	        operation: &RegistryPublishOperation,
283	        outdir: &std::path::Path,
284	    ) -> Result<(), GraphError> {
285	        let epoch = callisto_model::vcs::GitAccess::new(context.root(), context.runner()).commit_time("HEAD")?;
286	        let build = registry_argv::pypi_build_argv(context.root(), &operation.package_dir, outdir, epoch)?;
287	        let built = run_build_argv(context, &build)?;
288	        if built.exit_code != Some(0) {
289	            return Err(GraphError::ReleaseCommand {
290	                program: build.program.clone(),
291	                args: build.args.clone(),
292	                failure: CommandFailure::NonZeroExit {
293	                    exit_code: built.exit_code,
294	                    stderr: built.stderr,
295	                },
296	            });
297	        }
