    assert_eq!(programs, ["npm", "npm", "npm"], "{calls:?}");
    assert!(calls[0].1.contains(&"view".to_owned()), "{calls:?}");
    assert!(calls[1].1.contains(&"--workspace=a".to_owned()), "{calls:?}");
    for (_, _, cwd) in &calls {
        assert_eq!(cwd, &root.path().join("web"), "{calls:?}");
