1	//! Whether a version already on a registry names this repository, so adopting it can be flagged when it does not.
2	
3	/// `host/owner/repo` for a repository URL in any form a registry records, lowercased and without a `.git` suffix.
4	///
5	/// Reads `https://`, `git+https://`, `ssh://`, `git://`, `git@host:owner/repo`, `github:owner/repo` and npm's bare
6	/// `owner/repo` shorthand. Only the first two path segments count, so a `/tree/main` or `#readme` tail is ignored.
7	pub(crate) fn repository_identity(url: &str) -> Option<String> {
8	    let url = url.trim();
9	    let url = url.strip_prefix("git+").unwrap_or(url);
10	    let (host, path) = if let Some(rest) = url.strip_prefix("github:") {
11	        ("github.com", rest)
12	    } else if let Some((_, rest)) = url.split_once("://") {
13	        let rest = rest.rsplit_once('@').map_or(rest, |(_, after)| after);
14	        rest.split_once('/')?
15	    } else if let Some((front, path)) = url.split_once(':') {
16	        (front.rsplit_once('@').map_or(front, |(_, host)| host), path)
17	    } else if url.matches('/').count() == 1 && !url.contains('.') {
18	        ("github.com", url)
19	    } else {
20	        return None;
21	    };
22	    let host = host.split(':').next().unwrap_or(host);
23	    let path = path.split(['#', '?']).next().unwrap_or(path);
24	    let mut segments = path.split('/').filter(|segment| !segment.is_empty());
25	    let owner = segments.next()?;
26	    let repo = segments.next()?;
27	    let repo = repo.strip_suffix(".git").unwrap_or(repo);
28	    (!host.is_empty() && !repo.is_empty()).then(|| format!("{host}/{owner}/{repo}").to_ascii_lowercase())
29	}
