31	/// The repository a registry entry names and this repository, as `host/owner/repo`, when they differ.
32	///
33	/// `None` when the registry names no repository, when either side cannot be read as a repository, and when they
34	/// match: a missing or unreadable value proves nothing about who owns the name.
35	pub(crate) fn differing_repositories(registry_repository: Option<&str>, origin: &str) -> Option<(String, String)> {
36	    let registry = repository_identity(registry_repository?)?;
37	    let ours = repository_identity(origin)?;
38	    (registry != ours).then_some((registry, ours))
39	}
