41	/// The warning for adopting a published version whose registry entry names another repository, if it does.
42	pub(crate) fn foreign_repository_warning(
43	    package: &str,
44	    version: &str,
45	    registry_repository: Option<&str>,
46	    origin: &str,
47	) -> Option<String> {
48	    differing_repositories(registry_repository, origin).map(|(registry, ours)| {
49	        format!(
50	            "warning: {package} {version} is already published, and its registry entry names {registry}, not this \
51	             repository ({ours}). Callisto adopts the published version and tags this commit; check that the name is \
52	             yours."
53	        )
54	    })
55	}
